import subprocess, sys, re
def run(args,label, show_log=False):
    open("/tmp/test/req.log","w").close()
    p=subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, timeout=20)
    lines=open("/tmp/test/req.log").read().splitlines()
    paths=[]
    for l in lines:
        m=re.match(r'(\w+) (\S+)',l)
        if m: paths.append(m.group(1)+" "+m.group(2))
    print(f"=== {label} EXIT {p.returncode} ===")
    print("OUT:",p.stdout, end='' if p.stdout.endswith("\n") or not p.stdout else "\n")
    if p.stderr: print("ERR:",p.stderr)
    if show_log: print("PATHS:",paths)
    else: print("NPATHS",len(paths))
    return p,paths

if __name__=="__main__":
    base=["http://127.0.0.1:8765/","-w","/tmp/test/wordlist.txt","--no-color","-r"]
    run(base+["-S"],"silent -r",True)
    run(base+["--disable-validator"],"disable-validator -r",True)
    run(base+["-l"],"scan-listable",True)
    run(base+["--scrape-listable"],"scrape-listable",True)
    run(base+["-l","--scrape-listable"],"both listable",True)
PY
python3 /tmp/test/probe.py 2>&1 | head -n 300
"}

