            self.send_response(301); self.send_header("Location",p+"/"); self.send_header("Content-Length","0"); self.end_headers(); return
        b=b"notfound"; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
http.server.ThreadingHTTPServer(("127.0.0.1",8770),H).serve_forever()
