{"command":"cat > src/logging.rs << 'EOF'
use std::cell::Cell;
use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::Mutex;

pub static VERBOSITY: AtomicU8 = AtomicU8::new(0);
pub static STDOUT_LOCK: Mutex<()> = Mutex::new(());

thread_local! {
    pub static THREAD_ID: Cell<u64> = Cell::new(1);
}

pub fn set_verbosity(v: u8) {
    VERBOSITY.store(v, Ordering::Relaxed);
}
pub fn verbosity() -> u8 {
    VERBOSITY.load(Ordering::Relaxed)
}
pub fn set_thread_id(id: u64) {
    THREAD_ID.with(|t| t.set(id));
}
pub fn thread_id() -> u64 {
    THREAD_ID.with(|t| t.get())
}

#[repr(C)]
struct CTm {
    tm_sec: i32,
    tm_min: i32,
    tm_hour: i32,
    tm_mday: i32,
    tm_mon: i32,
    tm_year: i32,
    tm_wday: i32,
    tm_yday: i32,
    tm_isdst: i32,
    tm_gmtoff: i64,
    tm_zone: *const u8,
}
extern "C" {
    fn time(t: *mut i64) -> i64;
    fn localtime_r(timep: *const i64, result: *mut CTm) -> *mut CTm;
}
fn now_hms() -> (i32, i32, i32) {
    unsafe {
        let mut tm = CTm {
            tm_sec: 0,
            tm_min: 0,
            tm_hour: 0,
            tm_mday: 0,
            tm_mon: 0,
            tm_year: 0,
            tm_wday: 0,
            tm_yday: 0,
            tm_isdst: 0,
            tm_gmtoff: 0,
            tm_zone: std::ptr::null(),
        };
        let t = time(std::ptr::null_mut());
        if localtime_r(&t, &mut tm).is_null() {
            // Fall back to UTC from the epoch.
            let secs = t.rem_euclid(86400);
            return ((secs / 3600) as i32, ((secs % 3600) / 60) as i32, (secs % 60) as i32);
        }
        (tm.tm_hour, tm.tm_min, tm.tm_sec)
    }
}

pub fn print_line(s: &str) {
    let _guard = STDOUT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = writeln!(handle, "{}", s);
    let _ = handle.flush();
}
pub fn print_text(s: &str) {
    let _guard = STDOUT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = write!(handle, "{}", s);
    let _ = handle.flush();
}

pub fn info(silent: bool, msg: &str) {
    if !silent {
        print_line(&format!("[INFO] {}", msg));
    }
}
pub fn warn(msg: &str) {
    print_line(&format!("[WARN] {}", msg));
}

pub fn debug_log(target: &str, msg: &str) {
    if verbosity() >= 1 {
        let (h, m, s) = now_hms();
        print_line(&format!(
            "{:02}:{:02}:{:02} [DEBUG] ({}) {}: {}",
            h,
            m,
            s,
            thread_id(),
            target,
            msg
        ));
    }
}
pub fn trace_log(target: &str, msg: &str) {
    if verbosity() >= 2 {
        let (h, m, s) = now_hms();
        print_line(&format!(
            "{:02}:{:02}:{:02} [TRACE] ({}) {}: {}",
            h,
            m,
            s,
            thread_id(),
            target,
            msg
        ));
    }
}
pub fn trace_loc(target: &str, loc: &str, msg: &str) {
    if verbosity() >= 2 {
        let (h, m, s) = now_hms();
        print_line(&format!(
            "{:02}:{:02}:{:02} [TRACE] ({}) {}: [{}] {}",
            h,
            m,
            s,
            thread_id(),
            target,
            loc,
            msg
        ));
    }
}
