use std::collections::BTreeSet;

pub fn read_lines(path: &str) -> Vec<String> {
    let bytes = std::fs::read(path).unwrap();
    if bytes.is_empty() {
        panic!(
            "Error detecting file encoding of {} - is the file empty?",
            path
        );
    }
    let text = decode(bytes);
    text.lines().map(|s| s.to_string()).collect()
}

pub fn read_set(path: &str) -> BTreeSet<String> {
    read_lines(path).into_iter().collect()
}

fn clean_word(word: &str) -> String {
    let mut s = word;
    if let Some(stripped) = s.strip_prefix('/') {
        s = stripped;
    }
    if let Some(stripped) = s.strip_suffix('/') {
        s = stripped;
    }
    s.to_string()
}

pub fn read_wordlist(path: &str) -> BTreeSet<String> {
    read_lines(path)
        .iter()
        .map(|s| clean_word(s))
        .collect::<BTreeSet<String>>()
}

fn decode(bytes: Vec<u8>) -> String {
    if bytes.len() >= 2 && bytes[0] == 0xFF && bytes[1] == 0xFE {
        let units: Vec<u16> = bytes
            .chunks_exact(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect();
        return String::from_utf16_lossy(&units);
    }
    if bytes.len() >= 2 && bytes[0] == 0xFE && bytes[1] == 0xFF {
        let units: Vec<u16> = bytes
            .chunks_exact(2)
            .map(|c| u16::from_be_bytes([c[0], c[1]]))
            .collect();
        return String::from_utf16_lossy(&units);
    }
    match String::from_utf8(bytes.clone()) {
        Ok(s) => s,
        Err(_) => bytes.iter().map(|&b| windows_1252_char(b)).collect(),
    }
}

fn windows_1252_char(b: u8) -> char {
    match b {
        0x80 => '\u{20AC}',
        0x81 => '\u{0081}',
        0x82 => '\u{201A}',
