pub fn parse(matches: &ArgMatches) -> Config {
    // Hosts are collected first; a URI file is read here if present.
    let mut hosts: BTreeSet<Url> = BTreeSet::new();
    if let Some(uri_file) = matches.get_one::<String>("uri-file") {
        for line in wordlist::read_lines(uri_file) {
            match Url::parse(&line) {
                Ok(u) => {
                    hosts.insert(u);
                }
                Err(_) => {
                    println!("Invalid URL: {}", line);
                }
            }
        }
    }
    if let Some(u) = matches.get_one::<Url>("uri") {
        hosts.insert(u.clone());
    }
    if let Some(us) = matches.get_many::<Url>("uri_flag") {
        for u in us {
            hosts.insert(u.clone());
        }
    }
    if hosts.is_empty() {
        println!("No valid hosts were provided - exiting");
        std::process::exit(2);
    }

    // Prefixes are loaded before extensions.
    let mut prefixes: BTreeSet<String> = get_strings(matches, "prefixes").into_iter().collect();
    if let Some(prefix_file) = matches.get_one::<String>("prefix-file") {
        for line in wordlist::read_lines(prefix_file) {
            prefixes.insert(line);
        }
    }

    let mut extensions: BTreeSet<String> = get_strings(matches, "extensions").into_iter().collect();
    if let Some(extension_file) = matches.get_one::<String>("extension-file") {
        for line in wordlist::read_lines(extension_file) {
            extensions.insert(line);
        }
    }

    // Length ranges are parsed after the prefix/extension files.
    let mut hide_lengths: BTreeSet<LengthRange> = BTreeSet::new();
    for value in get_strings(matches, "length_blacklist") {
        if value.contains('-') {
            let parts: Vec<&str> = value.split('-').collect();
            if parts.len() != 2 {
                panic!("Ranges must be in the form `150-300`");
            }
            let start: usize = parts[0]
                .parse()
                .expect("Ranges must be in the form `150-300`");
            let end: usize = parts[1]
                .parse()
                .expect("Ranges must be in the form `150-300`");
            if start >= end {
                panic!("The start of a range must be smaller than the end");
            }
            hide_lengths.insert(LengthRange::Range(start, end));
        } else {
            let n: usize = value.parse().expect("Length range must be integers");
            hide_lengths.insert(LengthRange::Single(n));
        }
    }

    // Finally, the wordlist itself.
    let (wordlist, wordlist_display, wordlist_is_default) =
        if let Some(path) = matches.get_one::<String>("wordlist") {
            (
                wordlist::read_wordlist(path),
                path.clone(),
                false,
            )
        } else {
            let exe = std::env::current_exe().unwrap_or_else(|_| PathBuf::from("executable"));
            let default_path = exe
                .parent()
                .map(|p| p.join("dirble_wordlist.txt"))
                .unwrap_or_else(|| PathBuf::from("dirble_wordlist.txt"));
            if !default_path.exists() {
                eprintln!("[ERROR] Unable to find default wordlist");
                std::process::exit(1);
            }
            let display = default_path.to_string_lossy().to_string();
            (
                wordlist::read_wordlist(&display),
                display,
                true,
            )
        };

    let verb = match matches
        .get_one::<String>("http_verb")
        .map(|s| s.to_lowercase())
        .as_deref()
    {
        Some("head") => Verb::Head,
        Some("post") => Verb::Post,
        _ => Verb::Get,
    };

    let output_all = matches.get_one::<String>("output_all").cloned();
    let mut txt_outputs = Vec::new();
    if let Some(p) = matches.get_one::<String>("output_file") {
        txt_outputs.push(p.clone());
    }
    if let Some(p) = &output_all {
        txt_outputs.push(format!("{}.txt", p));
    }
    let mut json_outputs = Vec::new();
    if let Some(p) = matches.get_one::<String>("json_file") {
        json_outputs.push(p.clone());
    }
    if let Some(p) = &output_all {
        json_outputs.push(format!("{}.json", p));
    }
    let mut xml_outputs = Vec::new();
    if let Some(p) = matches.get_one::<String>("xml_file") {
        xml_outputs.push(p.clone());
    }
    if let Some(p) = &output_all {
        xml_outputs.push(format!("{}.xml", p));
    }

    let proxy = if matches.get_flag("burp") {
        ProxyMode::Explicit("http://localhost:8080".to_string())
    } else if matches.get_flag("no-proxy") {
        ProxyMode::Disabled
    } else if let Some(p) = matches.get_one::<String>("proxy") {
        ProxyMode::Explicit(p.clone())
    } else {
        ProxyMode::Env
    };

    Config {
        hosts,
        wordlist,
        wordlist_display,
        wordlist_is_default,
        prefixes,
        extensions,
        hide_lengths,
        verb,
        timeout: matches.get_one::<u32>("timeout").copied().unwrap_or(5),
        max_errors: matches.get_one::<u32>("max_errors").copied().unwrap_or(5),
        max_threads: matches
            .get_one::<u64>("max-threads")
            .copied()
            .unwrap_or(10) as u32,
        wordlist_split: matches
            .get_one::<u32>("wordlist_split")
            .copied()
            .unwrap_or(3),
        throttle: matches.get_one::<u32>("throttle").copied().unwrap_or(0),
        ignore_cert: matches.get_flag("ignore-cert"),
        show_htaccess: matches.get_flag("show-htaccess"),
        outputs: OutputSpecs {
            txt: txt_outputs,
            json: json_outputs,
            xml: xml_outputs,
        },
        proxy,
        username: matches.get_one::<String>("username").cloned(),
        password: matches.get_one::<String>("password").cloned(),
        scan_listable: matches.get_flag("scan-listable"),
        max_recursion_depth: matches.get_one::<i32>("max_recursion_depth").copied(),
        disable_recursion: matches.get_flag("disable-recursion"),
        scrape_listable: matches.get_flag("scrape-listable"),
        user_agent: matches.get_one::<String>("user_agent").cloned(),
        cookies: get_strings(matches, "cookie"),
        headers: get_strings(matches, "header"),
        silent: matches.get_flag("silent"),
        verbose: matches.get_count("verbose"),
        no_color: matches.get_flag("no-color"),
        code_blacklist: get_u32s(matches, "code_blacklist"),
        code_whitelist: get_u32s(matches, "code_whitelist"),
        disable_validator: matches.get_flag("disable-validator"),
        scan_401: matches.get_flag("scan-401"),
        scan_403: matches.get_flag("scan-403"),
        ext_sub: matches.get_flag("ext-sub"),
        force_extension: matches.get_flag("force-extension"),
    }
}
EOF
"}

