use crate::wordlist;
use clap::ArgMatches;
use std::collections::BTreeSet;
use std::path::PathBuf;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verb {
    Get,
    Head,
    Post,
}
impl Verb {
    pub fn as_str(&self) -> &'static str {
        match self {
            Verb::Get => "GET",
            Verb::Head => "HEAD",
            Verb::Post => "POST",
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LengthRange {
    Single(usize),
    Range(usize, usize),
}
impl LengthRange {
    fn key(&self) -> (usize, usize, usize) {
        match *self {
            LengthRange::Single(n) => (n, n, 0),
            LengthRange::Range(a, b) => (a, b, 1),
        }
    }
    pub fn contains(&self, size: usize) -> bool {
        match *self {
            LengthRange::Single(n) => size == n,
            LengthRange::Range(a, b) => size >= a && size <= b,
        }
    }
}
impl PartialOrd for LengthRange {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for LengthRange {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.key().cmp(&other.key())
    }
}
impl std::fmt::Display for LengthRange {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match *self {
            LengthRange::Single(n) => write!(f, "{}", n),
            LengthRange::Range(a, b) => write!(f, "{}-{}", a, b),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
