{"command":"cat > src/output.rs << 'EOF'
use crate::logging;
use std::collections::BTreeMap;
use std::fs::File;
use std::io::Write;
use url::Url;

#[derive(Clone, Debug)]
pub struct Discovered {
    pub url: String,
    pub code: u32,
    pub size: usize,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

impl Discovered {
    pub fn new(url: String) -> Self {
        Discovered {
            url,
            code: 0,
            size: 0,
            is_directory: false,
            is_listable: false,
            redirect_url: String::new(),
            found_from_listable: false,
        }
    }
}

fn colored_code(code: u32, colored: bool) -> String {
    if !colored {
        return code.to_string();
    }
    let color = match code {
        200..=299 => 32,
        300..=399 => 36,
        _ => 31,
    };
    format!("\x1b[{}m{}\x1b[0m", color, code)
}

pub fn format_item(item: &Discovered, colored: bool, indent: bool) -> String {
    let prefix = if item.is_listable {
        "L"
    } else if item.is_directory {
        "D"
    } else {
        "+"
    };
    let lead = if indent { "  " } else { "" };
    if item.found_from_listable && item.code == 0 {
        format!("{}{} {} (SCRAPED)", lead, prefix, item.url)
    } else if item.redirect_url.is_empty() {
        format!(
            "{}{} {} (CODE:{}|SIZE:{})",
            lead,
            prefix,
            item.url,
            colored_code(item.code, colored),
            item.size
        )
    } else {
        format!(
            "{}{} {} (CODE:{}|SIZE:{}|DEST:{})",
            lead,
            prefix,
            item.url,
            colored_code(item.code, colored),
            item.size,
            item.redirect_url
        )
    }
}

pub struct Collector {
    silent: bool,
    colored: bool,
    show_htaccess: bool,
    results: std::sync::Mutex<BTreeMap<String, Vec<Discovered>>>,
}

impl Collector {
    pub fn new(
        hosts: &std::collections::BTreeSet<Url>,
        silent: bool,
        colored: bool,
        show_htaccess: bool,
    ) -> Self {
        let mut map = BTreeMap::new();
        for host in hosts {
            map.insert(host.to_string(), Vec::new());
        }
        Collector {
            silent,
            colored,
            show_htaccess,
            results: std::sync::Mutex::new(map),
        }
    }

    pub fn add(&self, root: &Url, item: Discovered) {
        if !self.show_htaccess && item.code == 403 && item.url.contains("/.ht") {
            return;
        }
        {
            let mut results = self.results.lock().unwrap();
            results
                .entry(root.to_string())
                .or_insert_with(Vec::new)
                .push(item.clone());
        }
        if !self.silent {
            logging::print_line(&format_item(&item, self.colored, false));
        }
    }

    pub fn snapshot(&self) -> BTreeMap<String, Vec<Discovered>> {
        self.results.lock().unwrap().clone()
    }
}

fn parent_url(item_url: &str) -> String {
    if let Ok(mut u) = Url::parse(item_url) {
        u.set_query(None);
        u.set_fragment(None);
        let path = u.path().to_string();
        if let Some(pos) = path.rfind('/') {
            let parent = path[..=pos].to_string();
            u.set_path(&parent);
            return u.to_string();
        }
    }
    item_url.to_string()
}

fn group_key(item: &Discovered) -> String {
    if item.is_directory {
        item.url.clone()
    } else {
        parent_url(&item.url)
    }
}

pub fn sorted_items(items: &[Discovered]) -> Vec<Discovered> {
    let mut sorted = items.to_vec();
    sorted.sort_by_cached_key(|item| (group_key(item), item.url.clone()));
    sorted
}

fn build_sections(
    results: &BTreeMap<String, Vec<Discovered>>,
    colored: bool,
    indent: bool,
    trailing_blank: bool,
) -> String {
    let mut out = String::new();
    let host_count = results.len();
    for (idx, (root, items)) in results.iter().enumerate() {
        out.push_str(&format!("Dirble Scan Report for {}:\n", root));
        let sorted = sorted_items(items);
        if sorted.is_empty() && indent {
            out.push('\n');
        }
        for item in &sorted {
            if item.is_directory {
                out.push('\n');
            }
            out.push_str(&format_item(item, colored, indent));
            out.push('\n');
        }
        if trailing_blank {
            out.push('\n');
        } else if idx + 1 < host_count {
            out.push('\n');
        }
    }
    out
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn json_item(item: &Discovered) -> String {
    format!(
        "{{\"url\":\"{}\",\"code\":{},\"size\":{},\"is_directory\":{},\"is_listable\":{},\"redirect_url\":\"{}\",\"found_from_listable\":{}}}",
        json_escape(&item.url),
        item.code,
        item.size,
        item.is_directory,
        item.is_listable,
        json_escape(&item.redirect_url),
        item.found_from_listable
    )
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum OutputKind {
    Txt,
    Json,
    Xml,
}

pub struct OutputFile {
    pub kind: OutputKind,
    pub path: String,
    pub file: File,
}

pub fn create_outputs(specs: &crate::arg_parse::OutputSpecs) -> Vec<OutputFile> {
    let mut out = Vec::new();
    for path in &specs.txt {
        let file = match File::create(path) {
            Ok(f) => f,
            Err(e) => panic!("couldn't create {}: {}", path, e),
        };
        out.push(OutputFile {
            kind: OutputKind::Txt,
            path: path.clone(),
            file,
        });
    }
    for path in &specs.json {
        let file = match File::create(path) {
            Ok(f) => f,
            Err(e) => panic!("couldn't create {}: {}", path, e),
        };
        out.push(OutputFile {
            kind: OutputKind::Json,
            path: path.clone(),
            file,
        });
    }
    for path in &specs.xml {
        let file = match File::create(path) {
            Ok(f) => f,
            Err(e) => panic!("couldn't create {}: {}", path, e),
        };
        out.push(OutputFile {
            kind: OutputKind::Xml,
            path: path.clone(),
            file,
        });
    }
    out
}

pub fn generate_reports(
    results: &BTreeMap<String, Vec<Discovered>>,
    outputs: &mut Vec<OutputFile>,
    tty: bool,
    colored: bool,
) {
    if tty {
        let console = build_sections(results, colored, true, false);
        logging::print_text(&console);
    }

    let txt = build_sections(results, false, false, true);
    for output in outputs.iter_mut().filter(|o| o.kind == OutputKind::Txt) {
        let _ = output.file.write_all(txt.as_bytes());
        let _ = output.file.flush();
    }

    // Flatten the results in report order.
    let mut all_items: Vec<Discovered> = Vec::new();
    for (_root, items) in results.iter() {
        all_items.extend(sorted_items(items));
    }

    for output in outputs.iter_mut().filter(|o| o.kind == OutputKind::Json) {
        let _ = output.file.write_all(b"[");
        let _ = output.file.flush();
        if all_items.is_empty() {
            let empty = String::new();
            let end = empty.len().wrapping_sub(1);
            let _trimmed = &empty[..end];
        }
        let joined = all_items
            .iter()
            .map(json_item)
            .collect::<Vec<String>>()
            .join(",\n");
        let _ = output.file.write_all(joined.as_bytes());
        let _ = output.file.write_all(b"]");
        let _ = output.file.flush();
    }

    let mut xml = String::new();
    xml.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<dirble_scan>\n");
    for item in &all_items {
        xml.push_str(&format!(
            "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>\n",
            item.url, item.code, item.size, item.is_directory, item.is_listable, item.redirect_url, item.found_from_listable
        ));
    }
    xml.push_str("</dirble_scan>");
    for output in outputs.iter_mut().filter(|o| o.kind == OutputKind::Xml) {
        let _ = output.file.write_all(xml.as_bytes());
        let _ = output.file.flush();
    }
}
EOF
"}

