static GLOBAL_INIT: std::sync::Once = std::sync::Once::new();

#[derive(Clone, Debug)]
pub struct RawResponse {
    pub code: u32,
    pub body: Vec<u8>,
    pub headers: Vec<(String, String)>,
}

impl RawResponse {
    pub fn header(&self, name: &str) -> Option<String> {
        self.headers
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.clone())
    }
}

#[derive(Clone, Debug)]
pub struct CurlError {
    pub code: i32,
    pub extra: String,
}

impl CurlError {
    pub fn describe(&self) -> String {
        let desc = match self.code {
            1 => "Unsupported protocol".to_string(),
            2 => "Failed initialization".to_string(),
            3 => "URL using bad/illegal format or missing URL".to_string(),
            5 => "Couldn't resolve proxy name".to_string(),
            6 => "Couldn't resolve host name".to_string(),
            7 => "Couldn't connect to server".to_string(),
            8 => "Weird server reply".to_string(),
            18 => "Transferred a partial file".to_string(),
            22 => "HTTP page not retrieved".to_string(),
            28 => "Timeout was reached".to_string(),
            35 => "SSL connect error".to_string(),
            47 => "Maximum (47) redirects hit".to_string(),
            52 => "Server returned nothing (no headers, no data)".to_string(),
            55 => "Failed sending network data".to_string(),
            56 => "Failure with receiving network data".to_string(),
            60 => "SSL peer certificate or SSH remote key was not OK".to_string(),
            _ => unsafe {
                let p = curl_easy_strerror(self.code);
                if p.is_null() {
                    "Unknown error".to_string()
                } else {
                    CStr::from_ptr(p).to_string_lossy().to_string()
                }
            },
        };
        if self.extra.is_empty() {
            format!("[{}] {}", self.code, desc)
        } else {
            format!("[{}] {} ({})", self.code, desc, self.extra)
        }
    }
}

struct Collector {
    body: Vec<u8>,
    headers: Vec<(String, String)>,
}

extern "C" fn write_callback(
    ptr: *mut c_void,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if userdata.is_null() || ptr.is_null() {
        return 0;
    }
    unsafe {
        let collector = &mut *(userdata as *mut Collector);
        let data = std::slice::from_raw_parts(ptr as *const u8, total);
        collector.body.extend_from_slice(data);
    }
    total
}

extern "C" fn header_callback(
    ptr: *mut c_void,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if userdata.is_null() || ptr.is_null() {
        return 0;
    }
    unsafe {
        let collector = &mut *(userdata as *mut Collector);
        let data = std::slice::from_raw_parts(ptr as *const u8, total);
        let line = String::from_utf8_lossy(data);
        let line = line.trim_end_matches(|c| c == '\r' || c == '\n');
        if let Some(pos) = line.find(':') {
            let name = line[..pos].trim().to_string();
            let value = line[pos + 1..].trim().to_string();
            collector.headers.push((name, value));
        }
    }
    total
}

pub struct CurlClient {
    handle: *mut CURL,
    header_list: *mut curl_slist,
    error_buffer: Box<[u8; 256]>,
    config: Arc<Config>,
}

unsafe impl Send for CurlClient {}

impl CurlClient {
    pub fn new(config: Arc<Config>) -> Self {
        GLOBAL_INIT.call_once(|| unsafe {
            curl_global_init(3);
        });
        let handle = unsafe { curl_easy_init() };
        assert!(!handle.is_null(), "curl_easy_init failed");
        let mut client = CurlClient {
            handle,
            header_list: std::ptr::null_mut(),
            error_buffer: Box::new([0u8; 256]),
            config: config.clone(),
        };
        unsafe {
            curl_easy_setopt(handle, CURLOPT_ERRORBUFFER, client.error_buffer.as_mut_ptr() as *mut c_void);
            curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, write_callback as extern "C" fn(*mut c_void, usize, usize, *mut c_void) -> usize);
            curl_easy_setopt(handle, CURLOPT_HEADERFUNCTION, header_callback as extern "C" fn(*mut c_void, usize, usize, *mut c_void) -> usize);
            curl_easy_setopt(handle, CURLOPT_NOSIGNAL, 1i64);
            curl_easy_setopt(handle, CURLOPT_FOLLOWLOCATION, 0i64);
            curl_easy_setopt(handle, CURLOPT_TIMEOUT, config.timeout as i64);
            curl_easy_setopt(
                handle,
                CURLOPT_SSL_VERIFYPEER,
                if config.ignore_cert { 0i64 } else { 1i64 },
            );
            curl_easy_setopt(
                handle,
                CURLOPT_SSL_VERIFYHOST,
                if config.ignore_cert { 0i64 } else { 2i64 },
            );
            match &config.proxy {
                ProxyMode::Explicit(proxy) => {
                    if let Ok(c) = CString::new(proxy.as_str()) {
                        curl_easy_setopt(handle, CURLOPT_PROXY, c.as_ptr());
                    }
                    let no_proxy = std::env::var("no_proxy").or_else(|_| std::env::var("NO_PROXY"));
                    if let Ok(np) = no_proxy {
                        if let Ok(c) = CString::new(np) {
                            // CURLOPT_NOPROXY is 10177 in libcurl's type encoding.
                            curl_easy_setopt(handle, 10177, c.as_ptr());
                        }
                    }
                }
                ProxyMode::Disabled => {
                    let empty = CString::new("").unwrap();
                    curl_easy_setopt(handle, CURLOPT_PROXY, empty.as_ptr());
                }
                ProxyMode::Env => {}
            }
            if let (Some(username), Some(password)) = (&config.username, &config.password) {
                if let Ok(c) = CString::new(format!("{}:{}", username, password)) {
                    curl_easy_setopt(handle, CURLOPT_USERPWD, c.as_ptr());
                }
            }
            if !config.cookies.is_empty() {
                if let Ok(c) = CString::new(config.cookies.join("; ")) {
                    curl_easy_setopt(handle, CURLOPT_COOKIE, c.as_ptr());
                }
            }
            if let Some(agent) = &config.user_agent {
                if let Ok(c) = CString::new(agent.as_str()) {
                    curl_easy_setopt(handle, CURLOPT_USERAGENT, c.as_ptr());
