    pub fn perform(&mut self, url: &Url) -> Result<RawResponse, CurlError> {
        self.perform_str(url.as_str())
    }

    pub fn perform_str(&mut self, url_str: &str) -> Result<RawResponse, CurlError> {
        logging::trace_loc(
