                }
            },
        };
        if self.extra.is_empty() {
            format!("[{}] {}", self.code, desc)
        } else {
            format!("[{}] {} ({})", self.code, desc, self.extra)
        }
    }
}

struct Collector {
    body: Vec<u8>,
    headers: Vec<(String, String)>,
}

extern "C" fn write_callback(
    ptr: *mut c_void,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if userdata.is_null() || ptr.is_null() {
        return 0;
    }
    unsafe {
        let collector = &mut *(userdata as *mut Collector);
        let data = std::slice::from_raw_parts(ptr as *const u8, total);
        collector.body.extend_from_slice(data);
    }
    total
}

extern "C" fn header_callback(
    ptr: *mut c_void,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if userdata.is_null() || ptr.is_null() {
        return 0;
    }
    unsafe {
        let collector = &mut *(userdata as *mut Collector);
        let data = std::slice::from_raw_parts(ptr as *const u8, total);
        let line = String::from_utf8_lossy(data);
        let line = line.trim_end_matches(|c| c == '\r' || c == '\n');
        if let Some(pos) = line.find(':') {
            let name = line[..pos].trim().to_string();
            let value = line[pos + 1..].trim().to_string();
            collector.headers.push((name, value));
        }
    }
    total
}

