                    curl_easy_setopt(self.handle, CURLOPT_POST, 0i64);
                    curl_easy_setopt(self.handle, CURLOPT_NOBODY, 0i64);
                    curl_easy_setopt(self.handle, CURLOPT_HTTPGET, 1i64);
                }
                Verb::Head => {
                    curl_easy_setopt(self.handle, CURLOPT_POST, 0i64);
                    curl_easy_setopt(self.handle, CURLOPT_NOBODY, 1i64);
                }
                Verb::Post => {
                    curl_easy_setopt(self.handle, CURLOPT_NOBODY, 0i64);
                    curl_easy_setopt(self.handle, CURLOPT_POST, 1i64);
                }
            }
            for b in self.error_buffer.iter_mut() {
                *b = 0;
            }
            let code = curl_easy_perform(self.handle);
            if code != 0 {
                let extra = CStr::from_bytes_until_nul(&self.error_buffer[..])
                    .map(|s| s.to_string_lossy().trim().to_string())
                    .unwrap_or_default();
                return Err(CurlError { code, extra });
            }
            let mut response_code: i64 = 0;
            curl_easy_getinfo(
                self.handle,
                CURLINFO_RESPONSE_CODE,
                &mut response_code as *mut i64,
            );
            Ok(RawResponse {
                code: response_code as u32,
                body: std::mem::take(&mut collector.body),
                headers: std::mem::take(&mut collector.headers),
            })
        }
    }
}

impl Drop for CurlClient {
    fn drop(&mut self) {
        unsafe {
            if !self.header_list.is_null() {
                curl_slist_free_all(self.header_list);
            }
            if !self.handle.is_null() {
                curl_easy_cleanup(self.handle);
            }
        }
    }
}
