use crate::arg_parse::Config;
use crate::logging;
use crate::request::{CurlClient, RawResponse};
use std::collections::BTreeMap;
use std::io::Read;
use url::Url;

#[derive(Clone, Debug)]
pub enum Signature {
    Code(u32),
    CodeSize(u32, usize),
    CodeDiff(u32, u64),
    CodeDest(u32, String),
}

impl Signature {
    pub fn code(&self) -> u32 {
        match *self {
            Signature::Code(c) => c,
            Signature::CodeSize(c, _) => c,
            Signature::CodeDiff(c, _) => c,
            Signature::CodeDest(c, _) => c,
        }
    }
    pub fn display(&self) -> String {
        match self {
            Signature::Code(c) => format!("(CODE:{})", c),
            Signature::CodeSize(c, s) => format!("(CODE:{}|SIZE:{})", c, s),
            Signature::CodeDiff(c, d) => format!("(CODE:{}|DIFF_SIZE:{})", c, d),
            Signature::CodeDest(c, d) => {
                if d.is_empty() {
                    format!("(CODE:{})", c)
                } else {
                    format!("(CODE:{}|DEST:{})", c, d)
                }
            }
        }
    }
    pub fn matches(&self, code: u32, size: usize, url: &str, redirect_url: &str) -> bool {
        match self {
            Signature::Code(c) => code == *c,
            Signature::CodeSize(c, s) => code == *c && size == *s,
            Signature::CodeDiff(c, d) => {
                code == *c && (size as i128 - url.len() as i128).unsigned_abs() as u64 == *d
            }
            Signature::CodeDest(c, d) => code == *c && redirect_url == d,
        }
    }
}

#[derive(Clone, Debug)]
struct Sample {
    code: u32,
    size: usize,
    redirect_url: String,
    url: String,
}

fn random_string(len: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut bytes = vec![0u8; len];
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        let _ = f.read_exact(&mut bytes);
    } else {
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9e3779b97f4a7c15);
        let mut x = seed ^ (len as u64).wrapping_mul(0x2545F4914F6CDD1D);
        for b in bytes.iter_mut() {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *b = (x & 0xFF) as u8;
        }
    }
    bytes
        .iter()
        .map(|b| CHARS[(*b % 62) as usize] as char)
        .collect()
}

fn majority<T: Clone + PartialEq>(values: &[T]) -> Option<(T, usize)> {
    let mut best: Option<(T, usize)> = None;
    for v in values {
        let count = values.iter().filter(|x| *x == v).count();
        if best.as_ref().map(|(_, c)| count > *c).unwrap_or(true) {
            best = Some((v.clone(), count));
        }
    }
    best
}

fn build_signature(samples: &[Sample]) -> Signature {
    let codes: Vec<u32> = samples.iter().map(|s| s.code).collect();
    let (code, _count) = majority(&codes).unwrap();
    let selected: Vec<&Sample> = samples.iter().filter(|s| s.code == code).collect();
    if code == 404 {
        return Signature::Code(code);
    }
    if (300..400).contains(&code) {
        let dests: Vec<String> = selected.iter().map(|s| s.redirect_url.clone()).collect();
        if let Some((dest, count)) = majority(&dests) {
            if count >= 2 {
                return Signature::CodeDest(code, dest);
            }
        }
        return Signature::Code(code);
    }
    let sizes: Vec<usize> = selected.iter().map(|s| s.size).collect();
    if let Some((size, count)) = majority(&sizes) {
        if count >= 2 {
            return Signature::CodeSize(code, size);
        }
    }
    let diffs: Vec<u64> = selected
        .iter()
        .map(|s| (s.size as i128 - s.url.len() as i128).unsigned_abs() as u64)
        .collect();
    if let Some((diff, count)) = majority(&diffs) {
        if count >= 2 {
            return Signature::CodeDiff(code, diff);
        }
    }
    Signature::Code(code)
}

pub enum ValidationOutcome {
    Scan(Signature),
    Skip,
}

pub fn redirect_url_for(config: &Config, request_url: &Url, raw: &RawResponse) -> String {
    if raw.code == 301 || raw.code == 302 {
        let location = raw.header("Location").unwrap();
        let mut resolved = request_url.join(&location).unwrap();
        if let (Some(username), Some(password)) = (&config.username, &config.password) {
            let _ = resolved.set_username(username);
            let _ = resolved.set_password(Some(password));
        }
        resolved.to_string()
    } else {
        String::new()
    }
}

pub fn validate_directory(
    url: &Url,
    config: &Config,
    client: &mut CurlClient,
) -> ValidationOutcome {
    let mut samples: Vec<Sample> = Vec::new();
    for len in [10usize, 20, 30] {
        let random = random_string(len);
        let request_url = url.join(&random).unwrap();
        match client.perform(&request_url) {
            Ok(raw) => {
                let redirect_url = redirect_url_for(config, &request_url, &raw);
                samples.push(Sample {
                    code: raw.code,
                    size: raw.body.len(),
                    redirect_url,
                    url: request_url.to_string(),
                });
            }
            Err(e) => {
                logging::print_line(&format!(
                    "Curl error after requesting {} : {}",
                    request_url,
                    e.describe()
                ));
            }
        }
    }
    if samples.len() < 2 {
        logging::warn(&format!(
            "{} errored too often during validation, skipping scanning",
            url
        ));
        return ValidationOutcome::Skip;
    }
    let signature = build_signature(&samples);
    logging::info(
        config.silent,
        &format!(
            "Detected nonexistent paths for {} are {}",
            url,
            signature.display()
        ),
    );
    if signature.code() == 401 && !config.scan_401 {
        logging::info(
            config.silent,
            &format!(
                "Skipping {}: \n    Scanning of directories returning 401 is disabled.\n    Use the --scan-401 flag to scan this directory,\n    or provide a valid session token or credentials.",
                url
            ),
        );
        return ValidationOutcome::Skip;
    }
    if signature.code() == 403 && !config.scan_403 {
        logging::info(
            config.silent,
            &format!(
                "Skipping {}: \n    Scanning of directories returning 403 is disabled.\n    Use the --scan-403 flag to scan this directory,\n    or provide valid session token or credentials.",
                url
            ),
        );
        return ValidationOutcome::Skip;
    }
    ValidationOutcome::Scan(signature)
}
EOF
"}

