    pub prepared: bool,
    pub validator: Option<Signature>,
}

pub struct QueueState {
    pub jobs: VecDeque<DirJob>,
    pub visited: HashSet<String>,
}

pub struct ScanShared {
    pub config: Arc<Config>,
    pub collector: Arc<Collector>,
    pub words: Arc<Vec<String>>,
    pub queue: Mutex<QueueState>,
    pub next_thread_id: AtomicU64,
}

impl ScanShared {
    pub fn new(config: Arc<Config>, collector: Arc<Collector>) -> Self {
        let words: Vec<String> = config.wordlist.iter().cloned().collect();
        ScanShared {
            config,
            collector,
            words: Arc::new(words),
            queue: Mutex::new(QueueState {
                jobs: VecDeque::new(),
                visited: HashSet::new(),
            }),
            next_thread_id: AtomicU64::new(5),
        }
    }

    pub fn add_initial(&self, job: DirJob) {
        let mut queue = self.queue.lock().unwrap();
        queue.visited.insert(job.url.to_string());
        queue.jobs.push_back(job);
    }

    pub fn queue_directory(&self, url: Url, root: Url, depth: u32) {
        let mut queue = self.queue.lock().unwrap();
        if queue.visited.contains(url.as_str()) {
            return;
        }
        queue.visited.insert(url.to_string());
        queue.jobs.push_back(DirJob {
            url,
            root,
            depth,
            is_initial: false,
            split: self.config.wordlist_split,
            prepared: false,
            validator: None,
        });
    }

    pub fn pop_job(&self) -> Option<DirJob> {
        self.queue.lock().unwrap().jobs.pop_front()
    }
}

fn combos(config: &Config) -> Vec<(String, String)> {
    let mut prefixes: BTreeSet<String> = config.prefixes.clone();
    prefixes.insert(String::new());
    let mut extensions: BTreeSet<String> = config.extensions.clone();
    if !config.force_extension {
        extensions.insert(String::new());
    }
    let extension_list: Vec<String> = if config.force_extension && extensions.is_empty() {
        vec![String::new()]
    } else {
        extensions.iter().cloned().collect()
    };
    let mut out = Vec::new();
    for prefix in prefixes.iter() {
        for extension in extension_list.iter() {
            out.push((prefix.clone(), extension.clone()));
        }
    }
    out
}

fn transform_word(word: &str, prefix: &str, extension: &str, ext_sub: bool) -> String {
    if ext_sub {
        format!("{}{}", prefix, word.replace("%EXT%", extension))
    } else {
        format!("{}{}{}", prefix, word, extension)
    }
}

