}

fn passes_filters(
    config: &Config,
    validator: &Option<Signature>,
    item: &Discovered,
) -> bool {
    if !config.code_whitelist.is_empty() {
        if !config.code_whitelist.contains(&item.code) {
            logging::trace_loc(
                "dirble::request_thread",
                "src/request_thread.rs:163",
                &format!("[{}]: code {} not in whitelist", item.url, item.code),
            );
            return false;
        }
    } else if !config.code_blacklist.is_empty() && config.code_blacklist.contains(&item.code) {
        logging::trace_loc(
            "dirble::request_thread",
            "src/request_thread.rs:170",
            &format!("[{}]: code {} in blacklist", item.url, item.code),
        );
        return false;
    }
    if let Some(signature) = validator {
        if signature.matches(item.code, item.size, &item.url, &item.redirect_url) {
            logging::trace_loc(
                "dirble::request_thread",
                "src/request_thread.rs:179",
                &format!("[{}]: matches Not Found condition", item.url),
            );
            return false;
        }
    }
    if config
        .hide_lengths
        .iter()
        .any(|range| range.contains(item.size))
    {
        logging::trace_loc(
            "dirble::request_thread",
            "src/request_thread.rs:186",
            &format!("[{}]: length {} is in a blacklist range", item.url, item.size),
        );
        return false;
    }
    true
}

fn extract_hrefs(body: &[u8]) -> Vec<String> {
    let text = String::from_utf8_lossy(body).to_string();
    let bytes = text.as_bytes();
    let mut hrefs = Vec::new();
    let mut i = 0usize;
    while i + 1 < bytes.len() {
        if bytes[i] == b'<' && (bytes[i + 1] == b'a' || bytes[i + 1] == b'A') {
            let after = i + 2;
            if after < bytes.len()
                && (bytes[after].is_ascii_whitespace() || bytes[after] == b'>' || bytes[after] == b'/')
            {
                // Find the end of this tag, respecting quotes.
                let mut j = after;
                let mut quote: Option<u8> = None;
                while j < bytes.len() {
                    let c = bytes[j];
                    if let Some(q) = quote {
                        if c == q {
                            quote = None;
                        }
                    } else if c == b'"' || c == b'\'' {
                        quote = Some(c);
                    } else if c == b'>' {
                        break;
                    }
                    j += 1;
                }
                let tag = &text[after..j.min(text.len())];
                if let Some(href) = find_href_attribute(tag) {
                    hrefs.push(decode_html_entities(&href));
                }
                i = j;
                continue;
            }
        }
        i += 1;
    }
    hrefs
}

fn find_href_attribute(tag: &str) -> Option<String> {
    let lower = tag.to_lowercase();
    let bytes = lower.as_bytes();
    let mut pos = 0usize;
    while let Some(found) = lower[pos..].find("href") {
        let idx = pos + found;
        let before_ok = idx == 0 || !(bytes[idx - 1].is_ascii_alphanumeric() || bytes[idx - 1] == b'-' || bytes[idx - 1] == b'_');
        let mut p = idx + 4;
        while p < bytes.len() && bytes[p].is_ascii_whitespace() {
            p += 1;
        }
        if before_ok && p < bytes.len() && bytes[p] == b'=' {
            p += 1;
            while p < bytes.len() && bytes[p].is_ascii_whitespace() {
                p += 1;
            }
            if p >= tag.len() {
                return Some(String::new());
            }
            let first = bytes[p];
            if first == b'"' || first == b'\'' {
                let start = p + 1;
                let mut end = start;
                while end < bytes.len() && bytes[end] != first {
                    end += 1;
                }
                return Some(tag[start..end].to_string());
            }
            let start = p;
            let mut end = start;
            while end < bytes.len() && !bytes[end].is_ascii_whitespace() && bytes[end] != b'>' {
                end += 1;
            }
            return Some(tag[start..end].to_string());
        }
        pos = idx + 4;
    }
    None
}

fn decode_html_entities(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(pos) = rest.find('&') {
        out.push_str(&rest[..pos]);
        let tail = &rest[pos..];
        let end = match tail.find(';') {
            Some(e) if e <= 10 => e,
            _ => {
                out.push('&');
                rest = &tail[1..];
                continue;
            }
        };
        let entity = &tail[1..end];
        let decoded = match entity {
            "amp" => Some("&".to_string()),
            "lt" => Some("<".to_string()),
            "gt" => Some(">".to_string()),
            "quot" => Some("\"".to_string()),
            "apos" => Some("'".to_string()),
            _ if entity.starts_with("#x") || entity.starts_with("#X") => {
                u32::from_str_radix(&entity[2..], 16)
                    .ok()
                    .and_then(char::from_u32)
                    .map(|c| c.to_string())
            }
            _ if entity.starts_with('#') => entity[1..]
                .parse::<u32>()
                .ok()
                .and_then(char::from_u32)
                .map(|c| c.to_string()),
            _ => None,
        };
        if let Some(d) = decoded {
            out.push_str(&d);
        } else {
            out.push_str(&tail[..=end]);
        }
        rest = &tail[end + 1..];
    }
    out.push_str(rest);
    out
}

fn fetch_directory_item(
    client: &mut CurlClient,
    url: &Url,
    config: &Config,
) -> (Discovered, Option<Vec<u8>>) {
    match client.perform(url) {
        Ok(raw) => {
            let body = raw.body.clone();
            let mut item = build_item(url, &raw, config, true);
            item.is_directory = true;
            (item, Some(body))
        }
        Err(e) => {
            logging::print_line(&format!(
                "Curl error after requesting {} : {}",
                url,
                e.describe()
            ));
            let mut item = Discovered::new(url.to_string());
            item.is_directory = true;
            (item, None)
        }
    }
}

fn process_scrape(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    listable_item: &Discovered,
    body: &[u8],
    listable_depth: u32,
) {
    let config = &shared.config;
    for href in extract_hrefs(body) {
        let lower = href.to_lowercase();
        if !lower.ends_with('/') {
            continue;
        }
        if lower.starts_with('?') {
            continue;
        }
        let parent = &listable_item.url;
        let candidate_string = if lower.starts_with(parent) {
            lower.clone()
        } else if lower.contains("://") {
            lower.clone()
        } else if lower.starts_with('/') {
            match Url::parse(parent).and_then(|u| u.join(&lower)) {
                Ok(u) => u.to_string(),
                Err(_) => continue,
            }
        } else {
            format!("{}{}", parent, lower)
        };
        let candidate = match Url::parse(&candidate_string) {
            Ok(u) => u,
            Err(_) => continue,
        };
        if candidate.as_str() == parent.as_str() {
            continue;
        }
        if !candidate.as_str().starts_with(parent.as_str()) {
            continue;
        }
        let child_depth = listable_depth + 1;
        if !can_queue_depth(config, child_depth) {
            let mut placeholder = Discovered::new(candidate.to_string());
            placeholder.is_directory = true;
            placeholder.found_from_listable = true;
            shared.collector.add(&job.root, placeholder);
        } else {
            let (item, _body) = fetch_directory_item(client, &candidate, config);
            shared.collector.add(&job.root, item);
            shared.queue_directory(candidate, job.root.clone(), child_depth);
        }
    }
}

fn handle_directory_item(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    item: &Discovered,
    body: Option<Vec<u8>>,
    from_scraped: bool,
) {
    let config = &shared.config;
    let item_depth = job.depth + 1;
    let item_url = match Url::parse(&item.url) {
        Ok(u) => u,
        Err(_) => return,
    };
    if can_queue_depth(config, item_depth) {
        if item.is_listable {
            if config.scan_listable {
                shared.queue_directory(item_url.clone(), job.root.clone(), item_depth);
            }
        } else {
            shared.queue_directory(item_url.clone(), job.root.clone(), item_depth);
        }
    }
    if item.is_listable && config.scrape_listable && !from_scraped {
        if let Some(body) = body {
            process_scrape(shared, client, job, item, &body, item_depth);
        }
    }
}

fn process_word(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    transformed: &str,
) -> bool {
    let config = &shared.config;
    let request_url = job.url.join(transformed).unwrap();
    let raw = match client.perform(&request_url) {
        Ok(r) => r,
        Err(e) => {
            logging::print_line(&format!(
                "Curl error after requesting {} : {}",
                request_url,
                e.describe()
            ));
            return true;
        }
    };

    if raw.code == 301 || raw.code == 302 {
        let redirect_url = redirect_url_for(config, &request_url, &raw);
        let expected = format!("{}/", request_url.as_str());
        if redirect_url == expected {
            let dir_url = Url::parse(&expected).unwrap();
            let (item, body) = fetch_directory_item(client, &dir_url, config);
            shared.collector.add(&job.root, item.clone());
            handle_directory_item(shared, client, job, &item, body, false);
            return false;
        }
        let mut item = build_item(&request_url, &raw, config, false);
        item.redirect_url = redirect_url;
        if passes_filters(config, &job.validator, &item) {
            shared.collector.add(&job.root, item);
        }
        return false;
    }

    let item = build_item(&request_url, &raw, config, false);
    if passes_filters(config, &job.validator, &item) {
        shared.collector.add(&job.root, item);
    }
    false
}

pub fn scan_directory(shared: &Arc<ScanShared>, job: &DirJob) {
    let config = shared.config.clone();
    let combinations = combos(&config);
    let mut handles = Vec::new();
    for (prefix, extension) in combinations {
        for offset in 0..job.split {
            let id = shared.next_thread_id.fetch_add(1, Ordering::SeqCst);
            let shared_clone = shared.clone();
            let job_clone = job.clone();
            let prefix_clone = prefix.clone();
            let extension_clone = extension.clone();
            let handle = std::thread::spawn(move || {
                logging::set_thread_id(id);
                logging::debug_log(
                    "dirble::request_thread",
                    &format!("Scanning {}", job_clone.url),
                );
                let mut client = CurlClient::new(shared_clone.config.clone());
                let mut consecutive_errors: u32 = 0;
                if job_clone.split > 0 {
                    let words = shared_clone.words.clone();
                    let mut index = offset as usize;
                    while index < words.len() {
                        let transformed = transform_word(
                            &words[index],
                            &prefix_clone,
                            &extension_clone,
                            shared_clone.config.ext_sub,
                        );
                        let is_error =
                            process_word(&shared_clone, &mut client, &job_clone, &transformed);
                        if is_error {
                            consecutive_errors += 1;
                            if shared_clone.config.max_errors != 0
                                && consecutive_errors >= shared_clone.config.max_errors
                            {
                                // The warning names the URL which caused the
                                // thread to give up.
                                let url = job_clone
                                    .url
                                    .join(&transformed)
                                    .map(|u| u.to_string())
                                    .unwrap_or(transformed.clone());
                                logging::warn(&format!(
                                    "Thread scanning {} stopping due to multiple consecutive errors received",
                                    url
                                ));
                                break;
                            }
                        } else {
                            consecutive_errors = 0;
                        }
                        if shared_clone.config.throttle > 0 {
                            std::thread::sleep(std::time::Duration::from_millis(
                                shared_clone.config.throttle as u64,
                            ));
                        }
                        index += job_clone.split as usize;
                    }
                }
                logging::debug_log(
                    "dirble::request_thread",
                    &format!("Finished scanning {}", job_clone.url),
                );
            });
            handles.push(handle);
        }
    }
    let mut panicked = false;
    for handle in handles {
        if handle.join().is_err() {
            panicked = true;
        }
    }
    if panicked {
        loop {
            std::thread::park();
        }
    }
}
EOF
