fn process_scrape(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    listable_item: &Discovered,
    body: &[u8],
    listable_depth: u32,
) {
    let config = &shared.config;
    for href in extract_hrefs(body) {
        let lower = href.to_lowercase();
        if !lower.ends_with('/') {
            continue;
        }
        if lower.starts_with('?') {
            continue;
        }
        let parent = &listable_item.url;
        let candidate_string = if lower.starts_with(parent) {
            lower.clone()
        } else if lower.contains("://") {
            lower.clone()
        } else if lower.starts_with('/') {
            match Url::parse(parent).and_then(|u| u.join(&lower)) {
                Ok(u) => u.to_string(),
                Err(_) => continue,
            }
        } else {
            format!("{}{}", parent, lower)
        };
        let candidate = match Url::parse(&candidate_string) {
            Ok(u) => u,
            Err(_) => continue,
        };
        if candidate.as_str() == parent.as_str() {
            continue;
        }
        if !candidate.as_str().starts_with(parent.as_str()) {
            continue;
        }
        let child_depth = listable_depth + 1;
        if !can_queue_depth(config, child_depth) {
            let mut placeholder = Discovered::new(candidate.to_string());
            placeholder.is_directory = true;
            placeholder.found_from_listable = true;
            shared.collector.add(&job.root, placeholder);
        } else {
            let (item, _body) = fetch_directory_item(client, &candidate, config);
            shared.collector.add(&job.root, item);
            shared.queue_directory(candidate, job.root.clone(), child_depth);
        }
    }
}

fn handle_directory_item(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    item: &Discovered,
    body: Option<Vec<u8>>,
    from_scraped: bool,
) {
    let config = &shared.config;
    let item_depth = job.depth + 1;
    let item_url = match Url::parse(&item.url) {
        Ok(u) => u,
        Err(_) => return,
    };
    if can_queue_depth(config, item_depth) {
        if item.is_listable {
            if config.scan_listable {
                shared.queue_directory(item_url.clone(), job.root.clone(), item_depth);
            }
        } else {
            shared.queue_directory(item_url.clone(), job.root.clone(), item_depth);
        }
    }
    if item.is_listable && config.scrape_listable && !from_scraped {
        if let Some(body) = body {
            process_scrape(shared, client, job, item, &body, item_depth);
        }
    }
}

fn process_word(
    shared: &Arc<ScanShared>,
    client: &mut CurlClient,
    job: &DirJob,
    transformed: &str,
) -> bool {
    let config = &shared.config;
    let request_url = job.url.join(transformed).unwrap();
    let raw = match client.perform(&request_url) {
        Ok(r) => r,
        Err(e) => {
            logging::print_line(&format!(
                "Curl error after requesting {} : {}",
                request_url,
                e.describe()
            ));
            return true;
        }
    };

    if raw.code == 301 || raw.code == 302 {
        let redirect_url = redirect_url_for(config, &request_url, &raw);
        let expected = format!("{}/", request_url.as_str());
        if redirect_url == expected {
            let dir_url = Url::parse(&expected).unwrap();
            let (item, body) = fetch_directory_item(client, &dir_url, config);
            shared.collector.add(&job.root, item.clone());
            handle_directory_item(shared, client, job, &item, body, false);
            return false;
        }
        let mut item = build_item(&request_url, &raw, config, false);
        item.redirect_url = redirect_url;
        if passes_filters(config, &job.validator, &item) {
            shared.collector.add(&job.root, item);
        }
        return false;
    }

    let item = build_item(&request_url, &raw, config, false);
    if passes_filters(config, &job.validator, &item) {
        shared.collector.add(&job.root, item);
    }
    false
}

pub fn scan_directory(shared: &Arc<ScanShared>, job: &DirJob) {
    let config = shared.config.clone();
    let combinations = combos(&config);
    let mut handles = Vec::new();
    for (prefix, extension) in combinations {
        for offset in 0..job.split {
            let id = shared.next_thread_id.fetch_add(1, Ordering::SeqCst);
            let shared_clone = shared.clone();
            let job_clone = job.clone();
            let prefix_clone = prefix.clone();
            let extension_clone = extension.clone();
            let handle = std::thread::spawn(move || {
                logging::set_thread_id(id);
                logging::debug_log(
                    "dirble::request_thread",
                    &format!("Scanning {}", job_clone.url),
                );
                let mut client = CurlClient::new(shared_clone.config.clone());
                let mut consecutive_errors: u32 = 0;
                if job_clone.split > 0 {
                    let words = shared_clone.words.clone();
                    let mut index = offset as usize;
                    while index < words.len() {
                        let transformed = transform_word(
                            &words[index],
                            &prefix_clone,
                            &extension_clone,
                            shared_clone.config.ext_sub,
                        );
                        let is_error =
                            process_word(&shared_clone, &mut client, &job_clone, &transformed);
                        if is_error {
                            consecutive_errors += 1;
                            if shared_clone.config.max_errors != 0
                                && consecutive_errors >= shared_clone.config.max_errors
                            {
                                // The warning names the URL which caused the
                                // thread to give up.
                                let url = job_clone
                                    .url
                                    .join(&transformed)
                                    .map(|u| u.to_string())
                                    .unwrap_or(transformed.clone());
                                logging::warn(&format!(
                                    "Thread scanning {} stopping due to multiple consecutive errors received",
                                    url
                                ));
                                break;
                            }
                        } else {
                            consecutive_errors = 0;
                        }
                        if shared_clone.config.throttle > 0 {
                            std::thread::sleep(std::time::Duration::from_millis(
                                shared_clone.config.throttle as u64,
                            ));
                        }
                        index += job_clone.split as usize;
                    }
                }
                logging::debug_log(
                    "dirble::request_thread",
                    &format!("Finished scanning {}", job_clone.url),
                );
            });
            handles.push(handle);
        }
    }
    let mut panicked = false;
    for handle in handles {
        if handle.join().is_err() {
            panicked = true;
        }
    }
    if panicked {
        loop {
            std::thread::park();
        }
    }
}
