    let num_hosts = config.hosts.len() as u32;
    let mut prepared_jobs: Vec<DirJob> = Vec::new();
    for host in config.hosts.iter() {
        if !host.as_str().ends_with('/') {
            loop {
                std::thread::park();
            }
        }
        if let Some(max) = config.max_recursion_depth {
            if max < 0 && !config.disable_recursion {
                loop {
                    std::thread::park();
                }
            }
        }
        let mut job = DirJob {
            url: host.clone(),
            root: host.clone(),
            depth: 0,
            is_initial: true,
            split: config.wordlist_split,
            prepared: true,
            validator: None,
