        if validator_enabled(&config) {
            logging::set_thread_id(2);
            let outcome = validator::validate_directory(host, &config, &mut validator_client);
            logging::set_thread_id(1);
            match outcome {
                ValidationOutcome::Skip => continue,
                ValidationOutcome::Scan(signature) => job.validator = Some(signature),
            }
        }
        let candidate = if num_hosts == 0 {
            0
        } else {
            config.max_threads.saturating_sub(2) / num_hosts
        };
        if candidate > config.wordlist_split {
            logging::info(
                config.silent,
                &format!(
                    "Increasing wordlist-split for initial scan of {} to {}",
                    host, candidate
                ),
            );
            job.split = candidate;
        }
        prepared_jobs.push(job);
    }

    let mut outputs = output::create_outputs(&config.outputs);
    for job in prepared_jobs {
        shared.add_initial(job);
    }

    while let Some(mut job) = shared.pop_job() {
        if !job.prepared {
            if validator_enabled(&config) {
                logging::set_thread_id(2);
                let outcome =
                    validator::validate_directory(&job.url, &config, &mut validator_client);
                logging::set_thread_id(1);
                match outcome {
                    ValidationOutcome::Skip => continue,
                    ValidationOutcome::Scan(signature) => job.validator = Some(signature),
                }
            }
            job.split = config.wordlist_split;
        }
        request_thread::scan_directory(&shared, &job);
    }

    logging::set_thread_id(3);
    logging::debug_log(
        "dirble::output_thread",
        "Received signal to end, generating the report",
    );
    logging::set_thread_id(1);

    let results = collector.snapshot();
    let report_thread = std::thread::spawn(move || {
        output::generate_reports(&results, &mut outputs, tty, colored);
    });
    report_thread.join().unwrap();

    // ProxyMode is used during request setup; keep the import tied to the
    // configuration type for clarity.
    let _ = std::mem::size_of::<ProxyMode>();
}
EOF
