import subprocess, os, re, sys, glob, json
ORIG="/workspace/executable"; OURS="/workspace/target/debug/executable"
def normalize(s):
    # random validator strings 10/20/30
    s=re.sub(r'[A-Za-z0-9]{30}', 'R30', s)
