    s=re.sub(r'[A-Za-z0-9]{10}', 'R10', s)
    s=re.sub(r'\(\d+\)', '(TID)', s)
    s=re.sub(r'\d\d:\d\d:\d\d', 'TT:TT:TT', s)
    s=re.sub(r'after \d+ milliseconds', 'after X milliseconds', s)
    s=re.sub(r'after \d+ ms', 'after X ms', s)
    return s
def run(binary,args,label,outfiles=[]):
