    p=subprocess.run([binary]+args,capture_output=True,text=True,timeout=20)
    logs=""
    for f in ["/tmp/test/req.log"]:
        if os.path.exists(f): logs+=open(f).read()
    files={}
    for f in outfiles:
        if os.path.exists(f): files[f]=open(f,'rb').read().decode(errors='ignore')
        else: files[f]=None
    return p,logs,files

def compare(args,label,outfiles=[]):
    o,olog,of=run(ORIG,args,label,outfiles)
    u,ulog,uf=run(OURS,args,label,outfiles)
    ok=True
    if o.returncode!=u.returncode: print(f"[{label}] EXIT orig={o.returncode} ours={u.returncode}"); ok=False
    if sorted(normalize(o.stdout).splitlines())!=sorted(normalize(u.stdout).splitlines()):
        print(f"[{label}] STDOUT DIFF")
        print(" orig:",normalize(o.stdout)); print(" ours:",normalize(u.stdout)); ok=False
    if normalize(o.stderr)!=normalize(u.stderr):
        print(f"[{label}] STDERR DIFF\n orig:{normalize(o.stderr)}\n ours:{normalize(u.stderr)}"); ok=False
    # request paths: compare sorted path multiset after normalizing random logs (extract GET path)
    def paths(log):
        out=[]
        for l in log.splitlines():
            m=re.match(r'(\w+) (\S+)',l)
            if m:
                path=m.group(2)
                # normalize random validator segments
                parts=path.split('/')
                norm=[]
                for seg in parts:
                    if re.fullmatch(r'[A-Za-z0-9]{10}|[A-Za-z0-9]{20}|[A-Za-z0-9]{30}', seg): norm.append('RAND'+str(len(seg)))
                    else: norm.append(seg)
                out.append(m.group(1)+' '+ '/'.join(norm))
        return sorted(out)
    if paths(olog)!=paths(ulog):
        print(f"[{label}] REQ DIFF\n orig:{paths(olog)}\n ours:{paths(ulog)}"); ok=False
    for f in outfiles:
        if of[f]!=uf[f]:
            print(f"[{label}] FILE {f} DIFF\n orig:{of[f]!r}\n ours:{uf[f]!r}"); ok=False
    print(("PASS " if ok else "FAIL ")+label)
    return ok

