        elif path=="/gzip":
            body=gzip.compress(b"gzipped body")
            c.sendall(b"HTTP/1.1 200 OK\r\nContent-Encoding: gzip\r\nContent-Length: "+str(len(body)).encode()+b"\r\n\r\n"+body)
        elif path=="/close":
            c.sendall(b"HTTP/1.1 200 OK\r\n\r\nclose body no length")
        elif path=="/nocontent":
            c.sendall(b"HTTP/1.1 204 No Content\r\nContent-Length: 5\r\n\r\n")
        elif path=="/badstatus":
            c.sendall(b"WAT 999 Whatever\r\nContent-Length: 3\r\n\r\nabc")
        elif path=="/big":
            body=b"x"*100000
            c.sendall(b"HTTP/1.1 200 OK\r\nContent-Length: 100000\r\n\r\n"+body)
        elif path=="/redir-multi":
            c.sendall(b"HTTP/1.1 302 Found\r\nLocation: /first\r\nLocation: /second\r\nContent-Length: 0\r\n\r\n")
        else:
            body=b"notfound"; c.sendall(b"HTTP/1.1 404 Not Found\r\nContent-Length: 8\r\n\r\n"+body)
    except Exception: pass
    finally:
        try:c.close()
        except:pass
while True:
    cl,_=srv.accept(); threading.Thread(target=handle,args=(cl,),daemon=True).start()
