{"command":"python3 - << 'PY'
p='src/wordlist.rs'; s=open(p).read()
old='''    match String::from_utf8(bytes.clone()) {
        Ok(s) => s,
        Err(_) => bytes.iter().map(|&b| windows_1252_char(b)).collect(),
    }'''
new='''    match String::from_utf8(bytes.clone()) {
        Ok(s) => s,
        Err(e) => {
            // If valid UTF-8 text (including a multi-byte sequence)
            // precedes the first invalid byte, decode as UTF-8 with
            // replacement characters.  Otherwise the high bytes are
            // treated as Windows-1252 text.
            let prefix = &bytes[..e.utf8_error().valid_up_to()];
            if prefix.iter().any(|b| *b >= 0x80) {
                String::from_utf8_lossy(&bytes).to_string()
            } else {
                bytes.iter().map(|&b| windows_1252_char(b)).collect()
            }
        }
    }'''
assert old in s; s=s.replace(old,new); open(p,'w').write(s)
